$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $PSScriptRoot
$Utf8 = New-Object System.Text.UTF8Encoding $false
function Write-BackupFile([string]$RelativePath, [string]$Content) {
  $full = Join-Path $Root $RelativePath
  $dir = Split-Path -Parent $full
  if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [System.IO.File]::WriteAllText($full, $Content, $Utf8)
}

Write-BackupFile 'lib/backup-tables.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'lib/backup-jobs.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'lib/backup-service.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'routes/backup-api.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'backup-app.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'electron/backup-main.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'electron/backup-preload.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'public/backup/login.html' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'public/backup/index.html' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-BackupFile 'public/js/backup-app.js' ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')))
Write-Host 'Hangup Backup app files installed.'
